mapper.select:
/* PdaCargoMapper.selectInspectResultNotFinished : 화물조회 홀드 정보 조회 */ SELECT CASE WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'S' THEN '선별 ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'X' THEN 'XR ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y' AND UPPER(CODE) NOT IN ('C')), '') WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'P' THEN '통관 ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='SE_INSPECTION_CODE' AND USE_YN='Y'), '') WHEN SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 0, 2) = 'I' THEN '검역 ' + ISNULL((SELECT NAME_DEFAULT FROM TB_SMS_CODE_DETAIL WHERE CODE = SUBSTRING(ISNULL(C.INSPECTION_TYPE,''), 2, 4) AND ENT_CODE = #{entCode} AND GROUP_CODE='INSPECTION_TYPE' AND USE_YN='Y'), '') WHEN ISNULL(C.INSPECTION_TYPE,'') = 'B' THEN '거대'
WHEN ISNULL(C.INSPECTION_TYPE,'') = 'T' THEN '지재권' WHEN ISNULL(C.INSPECTION_TYPE,'') = 'A' THEN '집중' END AS BMS_INSPECTION_TYPE FROM TB_BMS_INSPECT_RESULT C WHERE IN_NO = #{IN_NO} AND INSPECTION_FINISH_YN = 'N' AND INSPECTION_TYPE IN ( 'P06','X03','X04','X05','X06','S03','S04','S05','S06','SC' ,'I5','I6','I7','I8','I9','I10','I11','I12' ,'J5','J6','J7','J8','J9','J10','J11','J12' ,'K5','K6','K7','K8','K9','K10','K11','K12'
,'S01', 'S02', 'X01', 'X02', 'P01', 'P02' ,'B','A','T','C' )

/* PdaCargoMapper.selectExistDivideCount : 화물조회 BL분할 등록 건수 조회 */
SELECT
	COUNT(BL5HF_NO)
FROM
	TB_BMS_5HF
WHERE
	CARGO_REFERENCE_NO = #{CARGO_REFERENCE_NO}
	AND DIVIDE_CLASS = '1';

/* PdaCargoMapper.selectCargoPrintNo : 화물 순번 조회 */
SELECT 
	PRINT_NO 
FROM TB_BMS_INSPECT_PRINT_NO 
WHERE CARGO_REFERENCE_NO = #{CARGO_REFERENCE_NO}

mapper.update:
	/* PdaCargoMapper.updateHold : POD 이력 insert */
	UPDATE TB_ECM_OD_HOLD SET
		HOLD_RELEASE_YN = #{releaseYn}
		, HOLD_RELEASE_REASON = #{releaseReason}
	    , HOLD_RELEASE_ATTN = #{updateUserId}
        , HOLD_RELEASE_DATE = GETDATE()
	WHERE OD_JOB_NO = #{odJobNo}
	AND CARRYIN_STOP_YN = 'N'
	AND CARRYOUT_STOP_YN = 'N'

mapper.insert:
/* PdaCargoMapper.insertPodHistory : POD 이력 insert */
	INSERT INTO ${podTableName}(
		   ENT_CODE
		  ,OD_JOB_NO
		  ,POD_STATUS
		  ,POD_NAME
		  ,POD_DATE
		  ,POD_TIME
		  ,REMARKS
		  ,REGISTER_USER_ID
		  ,REGISTER_DATE_TIME
		  ,UPDATE_USER_ID
		  ,UPDATE_DATE_TIME
	)VALUES(
		   #{entCode}
		  ,#{odJobNo}
		  ,#{podStatus}
		  ,#{podName}
		  ,GETDATE()
		  ,CONVERT(VARCHAR(5),GETDATE(), 108)
		  ,#{remarks}
		  ,#{updateUserId}
		  ,GETDATE()
		  ,#{updateUserId}
		  ,GETDATE()
	);

mapper.select:
/* PdaCargoMapper.selectEntBusOptionDate : 화물 조회 - 출고 후 재입고 반출통고/체화일자 조회 */
	SELECT
		CONVERT(VARCHAR(10),DATEADD(DAY,-30,DATEADD(MONTH, CAST( ISNULL(SET_VALUE,3) AS INT ), CONVERT(VARCHAR(10),GETDATE(),120))),120) AS OUT_NOTICE_DATE
     	, CONVERT(VARCHAR(10),DATEADD(MONTH, CAST( ISNULL(SET_VALUE,3) AS INT ), CONVERT(VARCHAR(10),GETDATE(),120)),120) AS PERIOD_OVER_DATE
	FROM 
		TB_SMS_ENT_BUS_OPTION
	WHERE
		ENT_CODE = #{entCode}
		AND ENT_BUSINESS_CODE = #{entBusinessCode}
		AND OPTION_CODE = 'A01'

